arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: GetEnvironmentVariable now returns "" instead
        // of null for empty env vars on Linux. Use IDictionary lookup to
        // distinguish "not set" from "explicitly empty".
        var envVars = Environment.GetEnvironmentVariables();
        if (!envVars.Contains("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        else
        {
            var val = (string?)envVars["MY_FLAG"];
            Console.WriteLine($"MY_FLAG is set to '{val}'");
        }
    }
}

